import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const ChampionsLeagueHeader = ({ activeSection }) => {
  const location = useLocation();
  const currentPath = location.pathname;

  return (
    <header className="bg-champions-blue p-4 flex justify-between items-center shadow-md relative">
      {/* Logo y título principal */}
      <div className="flex items-center">
        <div className="w-16 h-16 mr-2 overflow-hidden rounded-lg shadow-lg border border-champions-gold/30">
          <img 
            src="/images/logos/cc.png" 
            alt="Champions League Logo" 
            className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
          />
        </div>
        <div className="ml-4">
          <h2 className="text-white font-bold text-xl">UEFA Champions League</h2>
          <p className="text-blue-300 text-sm">Estadísticas Históricas</p>
        </div>
      </div>

      {/* Navegación */}
      <nav className="hidden md:flex space-x-6">
        <Link 
          to="/" 
          className={`text-white hover:text-champions-gold transition-colors ${currentPath === '/' ? 'text-champions-gold' : ''}`}
        >
          Inicio
        </Link>
        <Link 
          to="/equipos" 
          className={`text-white hover:text-champions-gold transition-colors ${currentPath === '/equipos' ? 'text-champions-gold' : ''}`}
        >
          Equipos
        </Link>
        <Link 
          to="/temporadas" 
          className={`text-white hover:text-champions-gold transition-colors ${currentPath === '/temporadas' ? 'text-champions-gold' : ''}`}
        >
          Temporadas
        </Link>
      </nav>

      {/* Trofeo decorativo */}
      <div className="hidden md:flex items-center">
        <div className="w-16 h-16 overflow-hidden">
          <img 
            src="/images/trophy.png" 
            alt="Champions Trophy" 
            className="w-full h-full object-contain animate-pulse"
          />
        </div>
      </div>
    </header>
  );
};

export default ChampionsLeagueHeader;
